 1	predicate IsEven(n: int)
 2	{
 3	    n % 2 == 0
 4	}
 5	
 6	predicate IsOdd(n: int)
 7	{
 8	    n % 2 != 0
 9	}
10	
11	predicate IsFirstEven(evenIndex: int, lst: seq<int>)
12	    requires 0 <= evenIndex < |lst|
13	    requires IsEven(lst[evenIndex])
14	{
15	    forall i :: 0 <= i < evenIndex ==> IsOdd(lst[i])
16	}
17	
18	predicate IsFirstOdd(oddIndex: int, lst: seq<int>)
19	    requires 0 <= oddIndex < |lst|
20	    requires IsOdd(lst[oddIndex])
21	{
22	    forall i :: 0 <= i < oddIndex ==> IsEven(lst[i])
23	}
24	
25	
26	method FirstEvenOddIndices(lst : seq<int>) returns (evenIndex: int, oddIndex : int)
27	    requires |lst| >= 2
28	    requires exists i :: 0 <= i < |lst| && IsEven(lst[i])
29	    requires exists i :: 0 <= i < |lst| && IsOdd(lst[i])
30	    ensures 0 <= evenIndex < |lst| && evenIndex != 0
31	    ensures 0 <= oddIndex < |lst|
32	    // This is the postcondition that ensures that it's the first, not just any
33	    ensures IsEven(lst[evenIndex]) && IsFirstEven(evenIndex, lst)
34	    ensures IsOdd(lst[oddIndex]) && IsFirstOdd(oddIndex, lst)
35	{
36	    for i := 0 to |lst|
37	        invariant 0 <= i <= |lst|
38	        invariant forall j :: 0 <= j < i ==> IsOdd(lst[j])
39	    {
40	        if IsEven(lst[i])
41	        {
42	            evenIndex := i;
43	            break;
44	        }
45	    }
46	
47	    for i := 0 to |lst|
48	        invariant 0 <= i <= |lst|
49	        invariant forall j :: 0 <= j < i ==> IsEven(lst[j])
50	    {
51	        if IsOdd(lst[i])
52	        {
53	            oddIndex := i;
54	            break;
55	        }
56	    }
57	}
58	
59	method ProductEvenOdd(lst: seq<int>) returns (product : int)
60	    requires |lst| >= 2
61	    requires exists i :: 0 <= i < |lst| && IsEven(lst[i])
62	    requires exists i :: 0 <= i < |lst| && IsOdd(lst[i])
63	    ensures exists i, j :: 0 <= i < |lst| && IsEven(lst[i]) && IsFirstEven(i, lst) && 
64	                           0 <= j < |lst| && IsOdd(lst[j])  && IsFirstOdd(j, lst) && product == lst[i] * lst[j]
65	{
66	    var evenIndex, oddIndex := FirstEvenOddIndices(lst);
67	    product := lst[evenIndex] * lst[oddIndex];
68	}

